+            <dt>Tracking Number</dt>
+            <dd>@_shipment.TrackingNumber</dd>
+
+            <dt>Status</dt>
+            <dd>@_shipment.Status</dd>
+
+            <dt>Current Location</dt>
+            <dd>@_shipment.Location</dd>
+
+            <dt>Estimated Delivery</dt>
+            <dd>@_shipment.EstimatedDelivery.ToString("f")</dd>
+        </dl>
+
+        <h2>Status History</h2>
+        @if (_shipment.StatusUpdates.Count == 0)
+        {
+            <p>No status updates yet.</p>
+        }
+        else
+        {
+            <table class="table">
+                <thead>
+                    <tr>
+                        <th>Time</th>
+                        <th>Description</th>
+                        <th>Location</th>
+                    </tr>
+                </thead>
+                <tbody>
+                    @foreach (var update in _shipment.StatusUpdates)
+                    {
+                        <tr>
+                            <td>@update.Timestamp.ToString("g")</td>
+                            <td>@update.Description</td>
+                            <td>@update.Location</td>
+                        </tr>
+                    }
+                </tbody>
+            </table>
+        }
+    </div>
+}
+
+@code {
+    [Parameter]
+    public string TrackingNumber { get; set; } = default!;
+
+    private ShipmentDetails? _shipment;
+    private bool _loading;
+    private string? _errorMessage;
+
+    private CancellationTokenSource? _cts;
+
+    protected override async Task OnParametersSetAsync()
+    {
+        await LoadShipmentAsync();
+    }
+
+    private async Task LoadShipmentAsync()
+    {
+        // Cancel any previous in-flight request
+        _cts?.Cancel();
+        _cts?.Dispose();
+        _cts = new CancellationTokenSource();
+        var ct = _cts.Token;
+
+        _loading = true;
+        _errorMessage = null;
+        _shipment = null;
+        StateHasChanged();
+
+        try
+        {
+            _shipment = await ShipmentService.GetShipmentAsync(TrackingNumber, ct);
+        }
+        catch (OperationCanceledException) when (ct.IsCancellationRequested)
+        {
+            // Navigation changed or component disposed — do nothing
+            return;
+        }
+        catch (TaskCanceledException)
+        {
+            Logger.LogWarning("Request timed out for tracking number {TrackingNumber}", TrackingNumber);
+            _errorMessage = "The request timed out. Please try again.";
+        }
+        catch (TimeoutException)
+        {
+            Logger.LogWarning("Timeout fetching shipment {TrackingNumber}", TrackingNumber);
+            _errorMessage = "The request timed out. Please try again.";
+        }
+        catch (Exception ex)
+        {
+            Logger.LogError(ex, "Error fetching shipment {TrackingNumber}", TrackingNumber);
+            _errorMessage = "Something went wrong while loading shipment details. Please try again.";
+        }
+        finally
+        {
+            _loading = false;
+            StateHasChanged();
+        }
+    }
+
+    private async Task RetryLoad()
+    {
+        await LoadShipmentAsync();
+    }
+
+    public void Dispose()
+    {
+        _cts?.Cancel();
+        _cts?.Dispose();
+    }
+}
